import * as dotenv from "dotenv";
dotenv.config({ path: ".env.local" });

import { db } from "../src/db";
import { users } from "../src/db/schema";
import { eq } from "drizzle-orm";

/**
 * One-time rebrand migration: point the six goddess rows' `avatar_url` at the
 * new sci-fi static art (generated by `npm run gen:scifi-art`). The DB
 * usernames stay unchanged — only the avatar image changes.
 *
 * Follows the pattern of the historical scripts/update-goddess-avatars.ts:
 * ensureGoddess never overwrites avatars afterwards, so this persists.
 *
 * Idempotent: safe to re-run. Run once at deploy time:
 *
 *   npm run rebrand:goddess-art
 */

const GODDESS_ART: Record<string, string> = {
  Goddess: "/TheArchitect.webp",
  "Goddess of Wealth": "/TheBanker.webp",
  "Goddess of Knowledge": "/TheOracle.webp",
  "Goddess of Fate": "/TheLocksmith.webp",
  "Goddess of Time": "/TheClockkeeper.webp",
  "Goddess of War": "/NullPointer.webp",
  // Bonus card row — same treatment (its DB username stays "Mass Hire").
  "Mass Hire": "/botnet.webp",
};

async function main() {
  console.log("Swapping goddess avatar art to sci-fi statics...");

  for (const [username, artPath] of Object.entries(GODDESS_ART)) {
    const result = await db
      .update(users)
      .set({ avatarUrl: artPath, updatedAt: new Date() })
      .where(eq(users.username, username))
      .returning({ id: users.id });

    if (result.length === 0) {
      console.warn(`  ⚠ ${username}: no DB row found (skipped)`);
    } else {
      console.log(`  • ${username} → ${artPath}`);
    }
  }

  console.log("✅ Done.");
  process.exit(0);
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});
